// Pond
ellipse(151,197,34,20,'#7b9e6a');ellipse(151,195,32,18,'#ddd6a2');ellipse(151,193,29,16,'#63a7a7');ellipse(151,191,26,13,'#86c4ba');rect(132,186,14,1,'#b4ded0');rect(156,196,15,1,'#aed9ca');ellipse(166,185,5,3,'#6f9b61');rect(164,182,2,2,'#f0d6a4');
// Garden beds
for(let r=0;r<3;r++)for(let c=0;c<5;c++){let x=269+c*7,y=215+r*7;rect(x,y,6,5,'#8c7550');if(state.upgrades.includes('garden')){rect(x+2,y-3,2,5,'#608750');rect(x+1,y-5,4,3,['#f0c883','#d88d84','#e5e2ae'][(r+c)%3]);}else rect(x+2,y+1,2,1,'#ae9767');}for(let x=263;x<309;x+=9){rect(x,236,2,7,'#b4a277');}rect(262,239,47,2,'#c7b586');
// Cave mountain
polygon([[364,106],[369,80],[381,65],[397,67],[410,79],[421,106],[418,123],[367,123]],'#778675');polygon([[369,99],[377,77],[388,72],[396,82],[404,79],[413,111],[410,120],[369,120]],'#909b80');rect(382,97,22,23,'#435650');rect(386,94,14,28,'#374b46');rect(390,100,7,21,'#293d3b');crystal(374,116);crystal(410,115,'#9fc0c6');
// Bridge
if(state.upgrades.includes('bridge')){rect(332,130,33,16,'#806b4d');for(let i=0;i<9;i++)rect(333+i*4,131,3,14,'#d1b580');rect(331,126,37,2,'#9b825b');rect(331,147,37,2,'#9b825b');for(let x=331;x<=365;x+=17){rect(x,124,2,9,'#75684b');rect(x,144,2,8,'#75684b');}}else{rect(331,132,8,14,'#9c8863');rect(359,132,8,14,'#9c8863');rect(338,136,4,3,'#bba173');}
const trees=[[80,127,1],[101,97,1],[129,91,.85],[150,107,.9],[166,91,.85],[85,165,1],[103,159,.9],[91,190,.8],[312,134,1],[296,112,.9],[262,105,.85],[246,92,.8],[327,192,.85],[307,245,.8],[187,232,.8],[117,225,.75],[76,148,.7]];trees.filter(t=>t[1]<player.y).forEach(t=>tree(...t));house();
