rect(242,166,14,5,'#99774e');rect(244,161,10,5,'#c7a370');rect(248,156,3,5,'#725e44');rect(248,151,15,6,'#e2cf97');rect(248,153,11,1,'#b59868');ellipse(232,201,9,4,'#b4a679');rect(228,195,8,6,'#9a7c55');rect(230,190,5,7,frame%50<25?'#e2ae59':'#f0c46b');rect(231,188,2,5,'#f3d78b');
locations.forEach((l,i)=>{let done=l.ids.every(n=>state.solved.includes(n)),locked=i===4&&!state.upgrades.includes('bridge');let bob=Math.floor(Math.sin(frame/22+i)*2);rect(l.x-8,l.y-27+bob,16,15,locked?'#72817a':done?'#577c54':'#fff3cc');rect(l.x-6,l.y-29+bob,12,2,locked?'#72817a':done?'#577c54':'#fff3cc');polygon([[l.x-3,l.y-12+bob],[l.x+3,l.y-12+bob],[l.x,l.y-8+bob]],locked?'#72817a':done?'#577c54':'#fff3cc');ctx.fillStyle=done?'#eef5c6':locked?'#e1e7d9':'#927141';ctx.font='bold 10px monospace';ctx.textAlign='center';ctx.fillText(locked?'×':done?'✓':'!',l.x,l.y-16+bob);});
