function canWalk(x,y){if(!inside(x,y,mainPoly)&&!(state.upgrades.includes('bridge')&&(inside(x,y,cavePoly)||(x>=327&&x<=371&&y>=127&&y<=151))))return false;if(((x-151)/31)**2+((y-193)/17)**2<1)return false;if(x>187&&x<241&&y>93&&y<148)return false;if(x>365&&x<423&&y>67&&y<124)return false;return true;}
let last=0;function tick(t){let dt=Math.min(40,t-last||16);last=t;if(!document.querySelector('dialog[open]')){let dx=(keys.has('right')||keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('left')||keys.has('a')||keys.has('arrowleft')?1:0),dy=(keys.has('down')||keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('up')||keys.has('w')||keys.has('arrowup')?1:0),speed=dt*.055/(dx&&dy?Math.sqrt(2):1);if(canWalk(player.x+dx*speed,player.y))player.x+=dx*speed;if(canWalk(player.x,player.y+dy*speed))player.y+=dy*speed;}draw();let n=locations.findIndex(l=>Math.hypot(l.x-player.x,l.y+15-player.y)<27);if(n!==near){near=n;$('#interaction').innerHTML=n>=0?`<button id="interactBtn">${n===4&&!state.upgrades.includes('bridge')?'⌑ Restore bridge to explore':'E · '+locations[n].name+' ↗'}</button>`:'';if(n>=0)$('#interactBtn').onclick=()=>visit(n);$('#region').textContent=n>=0?locations[n].name:player.y>230?'Sunlit beach':'Explorer’s clearing';}requestAnimationFrame(tick);}
window.addEventListener('keydown',e=>{if(document.querySelector('dialog[open]'))return;const k=e.key.toLowerCase();if(['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright','e'].includes(k)){e.preventDefault();keys.add(k);if(k==='e'&&near>=0&&!e.repeat)visit(near);}});window.addEventListener('keyup',e=>{keys.delete(e.key.toLowerCase());save();});window.addEventListener('blur',()=>{keys.clear();save();});document.addEventListener('visibilitychange',()=>{keys.clear();save();});document.querySelectorAll('[data-dir]').forEach(b=>{b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys.add(b.dataset.dir);};b.onpointerup=b.onpointercancel=()=>{keys.delete(b.dataset.dir);save();};});canvas.onclick=e=>{const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)/r.width*480,y=(e.clientY-r.top)/r.height*300;const i=locations.findIndex(l=>Math.hypot(l.x-x,l.y-16-y)<24);if(i>=0)visit(i);else{canvas.focus({preventScroll:true});toast('Walk with WASD / arrows, or tap a glowing marker.');}};
update();requestAnimationFrame(tick);
